     5	public class ClaimOffice {
     6	
     7	    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
     8	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = rate(10);
     9	    private static final BigDecimal CURSE_SURCHARGE_RATE = rate(50);
    10	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = rate(30);
    11	
    12	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = rate(20);
    13	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = rate(15);
    14	
    15	    /** From this many years of business on, the MHPCO calls a customer long-standing. */
    16	    private static final int LONG_STANDING_YEARS = 2;
    17	
    18	    /** From this enchantment level on, the MHPCO considers an item highly enchanted. */
    19	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    20	
    21	    private final Customer customer;
    22	    private final ContractHistory contractHistory = new ContractHistory();
    23	
    24	    public ClaimOffice(Customer customer) {
    25	        this.customer = customer;
    26	    }
    27	
    28	    /**
    29	     * The office quotes the premium for the items and, in doing so, writes the
    30	     * contract: the premium is priced against the customer's file as it stands, and
    31	     * only then does the new contract enter that file.
    32	     */
    33	    public int quote(List<Item> items) {
    34	        int premium = premiumFor(items);
    35	        contractHistory.recordContractWritten();
    36	        return premium;
    37	    }
    38	
    39	    /** What the office charges for these items: every scope's contribution, plus the fee. */
    40	    private int premiumFor(List<Item> items) {
    41	        BigDecimal policyBasePremium = MhpcoPriceList.policyBasePremiumOf(items);
    42	        BigDecimal premiumBeforeFee = policyScopeContribution(policyBasePremium)
    43	                .add(itemScopeContribution(items));
    44	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
    45	    }
    46	
    47	    /**
    48	     * What the item scope contributes: the MHPCO charges a risk surcharge for each
    49	     * risky item as a share of that item's own base premium, never of the policy total.
    50	     */
    51	    private static BigDecimal itemScopeContribution(List<Item> items) {
    52	        return items.stream()
    53	                .map(ClaimOffice::riskSurchargeFor)
    54	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    55	    }
    56	
    57	    private static BigDecimal riskSurchargeFor(Item item) {
    58	        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
    59	        BigDecimal surcharge = BigDecimal.ZERO;
    60	        if (item.cursed()) {
    61	            surcharge = surcharge.add(shareOf(itemBasePremium, CURSE_SURCHARGE_RATE));
    62	        }
    63	        if (isHighlyEnchanted(item)) {
    64	            surcharge = surcharge.add(
    65	                    shareOf(itemBasePremium, HIGH_ENCHANTMENT_SURCHARGE_RATE));
    66	        }
    67	        return surcharge;
    68	    }
    69	
    70	    private static boolean isHighlyEnchanted(Item item) {
    71	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    72	    }
    73	
    74	    /**
    75	     * What the policy scope contributes: the policy base premium itself, adjusted by
    76	     * the modifiers the office applies to the policy as a whole.
    77	     */
    78	    private BigDecimal policyScopeContribution(BigDecimal policyBasePremium) {
    79	        BigDecimal contribution = policyBasePremium
    80	                .add(shareOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_RATE));
    81	        if (isLongStanding()) {
    82	            contribution = contribution
    83	                    .subtract(shareOf(policyBasePremium, LOYALTY_DISCOUNT_RATE));
    84	        }
    85	        if (contractHistory.nextContractIsFollowUp()) {
    86	            contribution = contribution
    87	                    .subtract(shareOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_RATE));
    88	        }
    89	        return contribution;
    90	    }
    91	
    92	    /** Two years of business with the MHPCO make a customer long-standing. */
    93	    private boolean isLongStanding() {
    94	        return customer.yearsWithMHPCO() >= LONG_STANDING_YEARS;
    95	    }
    96	
    97	    /** A modifier is a percentage share of the amount it applies to. */
    98	    private static BigDecimal shareOf(BigDecimal amount, BigDecimal modifierRate) {
    99	        return amount.multiply(modifierRate);
   100	    }
   101	
   102	    /** A modifier rate stated the way the price list states it: in whole percent. */
   103	    private static BigDecimal rate(int percent) {
   104	        return BigDecimal.valueOf(percent, 2);
   105	    }
   106	
   107	    /**
   108	     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
   109	     * amounts stay exact fractions, so only this final step loses the remainder.
   110	     */
   111	    private static int roundInOfficeFavour(BigDecimal premium) {
   112	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
   113	    }
   114	}
