     1	/**
     2	 * What the MHPCO has on file about a customer's contracts so far. The office keeps
     3	 * this tally per customer: it decides whether a new contract is the customer's first
     4	 * or a follow-up, which is the only thing the premium calculation asks of it.
     5	 */
     6	public final class ContractHistory {
     7	
     8	    private int contractsWritten;
     9	
    10	    /** Every contract after the customer's first is a follow-up contract. */
    11	    public boolean nextContractIsFollowUp() {
    12	        return contractsWritten > 0;
    13	    }
    14	
    15	    /** The office notes in the file that it has written another contract. */
    16	    public void recordContractWritten() {
    17	        contractsWritten++;
    18	    }
    19	}
